"""Islamiat (Ikhtiari) XII PDF72: pp.134–135 — hadith 41 (the Ansari host; Al-Hashr 9). Run: python class12_iski_page072.py"""
from class12_iski_common import BOOK, Builder, rec, P, AR


def p72():
    b = Builder()
    b.h('[Hadith] no. 41', '[حدیث] نمبر 41', '[حدیث] نمبر ۴۱')
    AR(b, 'عَنْ اَبِيْ هُرَيْرَةَ رَضِيَ اللّٰهُ عَنْهُ اَنَّ رَجُلًا اَتَى النَّبِيَّ صَلَّى اللّٰهُ عَلَيْهِ وَآلِهٖ وَسَلَّمَ فَبَعَثَ اِلٰى نِسَآئِهٖ فَقُلْنَ: مَا مَعَنَا اِلَّا الْمَآءُ، فَقَالَ رَسُوْلُ اللّٰهِ صَلَّى اللّٰهُ عَلَيْهِ وَآلِهٖ وَسَلَّمَ: مَنْ يَّضُمُّ اَوْ يُضِيْفُ هٰذَا؟ فَقَالَ رَجُلٌ مِّنَ الْاَنْصَارِ: اَنَا فَانْطَلَقَ بِهٖ اِلَى امْرَاَتِهٖ، فَقَالَ: اَكْرِمِيْ ضَيْفَ رَسُوْلِ اللّٰهِ صَلَّى اللّٰهُ عَلَيْهِ وَآلِهٖ وَسَلَّمَ فَقَالَتْ: مَا عِنْدَنَا اِلَّا قُوْتُ صِبْيَانِيْ، فَقَالَ هَيِّئِيْ طَعَامَكِ، وَاَصْبِحِيْ سِرَاجَكِ وَنَوِّمِيْ صِبْيَانَكِ اِذَا اَرَادُوْا عَشَآءً، فَهَيَّاَتْ طَعَامَهَا، وَاَصْبَحَتْ سِرَاجَهَا وَنَوَّمَتْ صِبْيَانَهَا، ثُمَّ قَامَتْ كَاَنَّهَا تُصْلِحُ سِرَاجَهَا فَاَطْفَاَتْهُ، فَجَعَلَا يُرِيَانِهٖ اَنَّهُمَا يَاْكُلَانِ فَبَاتَا طَاوِيَيْنِ فَلَمَّا اَصْبَحَ غَدَا اِلٰى رَسُوْلِ اللّٰهِ فَقَالَ: "ضَحِكَ اللّٰهُ اللَّيْلَةَ اَوْ عَجِبَ مِنْ فِعَالِكُمَا" فَاَنْزَلَ اللّٰهُ "وَيُؤْثِرُوْنَ عَلٰٓى اَنْفُسِهِمْ وَلَوْ كَانَ بِهِمْ خَصَاصَةٌ ۚ وَمَنْ يُّوْقَ شُحَّ نَفْسِهٖ فَاُولٰٓئِكَ هُمُ الْمُفْلِحُوْنَ"', 'صحیح مسلم و صحیح البخاری')
    b.p('Translation: It is narrated from Hazrat Abu Hurayrah (may Allah be pleased with him) that a man came to him ﷺ (as a guest). He ﷺ told his wives. They said that we have nothing except water. Then the Noble Prophet ﷺ said: who will take him along with himself, or who will host him? A man of the Ansar said: I. He took him to his home and said: honour the guest of the Noble Prophet ﷺ. She began to say: we have only the children\'s food. He said: you bring the food, put the children to sleep, and light the lamp when we intend to eat at night. She prepared the food, lit the lamp and put the children to sleep; then she stood up as if she were adjusting the lamp, and extinguished the lamp. So they made it appear that they too were sharing the meal with the guest …', 'ترجمہ: حضرت ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ ایک آدمی آپ صلی اللہ علیہ وآلہٖ وسلم کے پاس (بطورِ مہمان) آیا۔ آپ صلی اللہ علیہ وآلہٖ وسلم نے اپنی ازواج کو کہا۔ انہوں نے کہا کہ ہمارے پاس پانی کے سوا کچھ نہیں۔ تو نبی اکرمؐ نے فرمایا کہ کون اس کو اپنے ساتھ ملائے گا۔ یا اس کی مہمان نوازی کرے گا۔ انصار کے ایک آدمی نے کہا کہ میں۔ وہ اسے اپنے گھر لے گیا اور کہا کہ تم نبی اکرم صلی اللہ علیہ وآلہٖ وسلم کے مہمان کا اکرام کرو۔ وہ کہنے لگی ہمارے پاس تو صرف بچوں کا کھانا ہے۔ اس نے کہا تم کھانا لے آنا، بچوں کو سلا دینا اور چراغ جلا دینا۔ جب ہم رات کے کھانے کا ارادہ کریں۔ اس نے کھانا تیار کیا اور چراغ روشن کیا اور بچوں کو سلا دیا پھر وہ کھڑی ہوئی گویا چراغ ٹھیک کر رہی ہے اور چراغ کو بجھا دیا۔ پس انہوں نے یہ ظاہر کیا کہ وہ بھی مہمان کے ساتھ', 'ژباړه: له حضرت ابوهریره رضي الله عنه روایت دی چې یو سړی هغه ﷺ ته (د مېلمه په توګه) راغی. هغه ﷺ خپلو مېرمنو ته وویل. هغوی وویل چې موږ سره له اوبو پرته هېڅ نشته. نو نبي اکرم ﷺ وفرمایل: څوک به یې له ځان سره بوځي، یا یې مېلمستیا وکړي؟ د انصارو یوه سړي وویل: زه. هغه یې خپل کور ته بوت او ویې ویل: د نبي اکرم ﷺ د مېلمه درناوی وکړه. هغې وویل: موږ سره یوازې د ماشومانو خواړه دي. هغه وویل: ته خواړه راوړه، ماشومان ویده کړه، او کله چې د شپې د ډوډۍ اراده وکړو، څراغ بل کړه. هغې خواړه تیار کړل، څراغ یې بل کړ او ماشومان یې ویده کړل؛ بیا ودرېده لکه چې څراغ سموي، او څراغ یې مړ کړ. نو دوی داسې ښکاره کړه چې ګواکې دوی هم له مېلمه سره …')
    r1 = rec(b, 2, 134, 72, [134])
    t = Builder()
    P(t, [('… sharing the food. Both of them spent the night hungry. When morning came, they went to the Noble Prophet ﷺ, and he ﷺ said that Allah the Exalted was pleased with you during the night and liked your deed. So Allah the Exalted sent down this verse: "They give preference to others over themselves even though they themselves be hungry, and whoever is saved from the greed of the self, those are the ones who attain success."', 'کھانے میں شریک ہیں۔ ان دونوں نے بھوکے رات گزاری۔ صبح ہوئی تو نبی اکرم صلی اللہ علیہ وآلہٖ وسلم کی طرف چلے اور آپ صلی اللہ علیہ وآلہٖ وسلم نے فرمایا کہ اللہ تعالیٰ رات کو تم پر خوش ہوئے اور تمہارے عمل کو پسند کیا۔ پس اللہ تعالیٰ نے یہ آیت نازل کی ”وہ دوسروں کو اپنے نفسوں پر ترجیح دیتے ہیں اگرچہ خود بھوکے ہوں اور جو بچایا گیا نفس کے لالچ سے پس وہی لوگ فلاح پانے والوں میں سے ہیں“', '… په ډوډۍ کې شریک دي. دواړو وږي شپه تېره کړه. کله چې سهار شو، نبي اکرم ﷺ ته لاړل، او هغه ﷺ وفرمایل: الله تعالی د شپې پر تاسو خوشاله شو او ستاسو عمل یې خوښ کړ. نو الله تعالی دا آیت نازل کړ: «هغوی نور پر خپلو ځانونو غوره ګڼي که څه هم پخپله وږي وي؛ او څوک چې د نفس له حرصه وژغورل شو، همدوی بریالي دي.»')])
    t.h('Explanation', 'تشریح', 'تشریح')
    t.p('In this blessed hadith a reference has been made to such an incident in which a Companion (may Allah be pleased with him), giving preference to the guest of the Noble Messenger ﷺ over his household and his own self, fed him the food, and Allah the Exalted liked this deed of theirs so much that this blessed verse of the Wise Quran was sent down.', 'اس حدیثِ مبارکہ میں ایک ایسے واقعے کی طرف اشارہ کیا گیا ہے جس میں ایک صحابی رضی اللہ عنہ نے رسول کریم صلی اللہ علیہ وآلہٖ وسلم کے مہمان کو اپنے اہلِ خانہ اور اپنی ذات پر ترجیح دیتے ہوئے کھانا کھلایا تھا اور اللہ تعالیٰ کو ان کا یہ فعل اتنا پسند آیا کہ قرآنِ حکیم کی یہ آیتِ مبارکہ نازل ہوئی تھی۔', 'په دې مبارک حدیث کې داسې پېښې ته اشاره شوې چې په کې یوه صحابي رضي الله عنه د رسول کریم ﷺ مېلمه پر خپلې کورنۍ او ځان غوره وګاڼه او ډوډۍ یې ورکړه، او الله تعالی ته یې دا عمل دومره خوښ شو چې د قرآن حکیم دا مبارک آیت نازل شو.')
    AR(t, 'وَيُؤْثِرُوْنَ عَلٰٓى اَنْفُسِهِمْ وَلَوْ كَانَ بِهِمْ خَصَاصَةٌ', 'الحشر: ۹')
    P(t, [('Translation: [They give preference to others] over themselves, even though they have an intense desire.', 'ترجمہ: [اپنے آپ] پر دوسروں کو ترجیح دیتے ہیں خواہ انہیں شدید خواہش ہو۔', 'ژباړه: [نور] پر ځان غوره ګڼي، که څه هم دوی ته سخته اړتیا وي.'),
          ('[Once,] in the court of the Noble Prophet ﷺ, a person came as a guest. For his service there was nothing in the house of him ﷺ except water. At his ﷺ saying, a Companion took this guest to his own house. In their house too there was very little food. The Companion said to his wife: you put the food in front of us, and on the pretext of fixing the lamp, extinguish it, and put the children to sleep hungry. His wife did exactly that. That Companion (may Allah be pleased with him), in the darkness, made it appear that he too was sharing the food. On this service of the guest of the Noble Messenger ﷺ, Allah the Exalted sent down revelation.', '[ایک بار نبی] کریم صلی اللہ علیہ وآلہٖ وسلم کی بارگاہ میں ایک شخص مہمان بن کر آیا۔ اس کی خدمت کے لیے آپ صلی اللہ علیہ وآلہٖ وسلم کے گھر میں پانی کے علاوہ کچھ نہ تھا۔ آپؐ کے کہنے پر ایک صحابی اس مہمان کو اپنے گھر لے گیا۔ ان کے گھر بھی بہت کم کھانا تھا۔ صحابی نے اپنی بیوی سے کہا کہ تم کھانا ہمارے سامنے رکھ دینا اور چراغ کو درست کرنے کے بہانے گل کر دینا اور بچوں کو بھوکے ہی سلا دینا۔ ان کی بیوی نے ایسا ہی کیا۔ ان صحابی رضی اللہ عنہ نے اندھیرے میں یہ ظاہر کیا کہ وہ بھی کھانے میں شریک ہیں۔ اس طرح رسولِ اکرم صلی اللہ علیہ وآلہٖ وسلم کے مہمان کی خدمت کرنے پر اللہ تعالیٰ نے وحی نازل فرمائی۔', '[یو ځل] د نبي کریم ﷺ دربار ته یو سړی د مېلمه په توګه راغی. د هغه د خدمت لپاره د هغه ﷺ په کور کې له اوبو پرته هېڅ نه وو. د هغه ﷺ په وینا یوه صحابي دا مېلمه خپل کور ته بوت. د هغوی په کور کې هم ډېر لږ خواړه وو. صحابي خپلې مېرمنې ته وویل: ته خواړه زموږ مخې ته کېږده، د څراغ د سمولو په پلمه یې مړ کړه، او ماشومان وږي ویده کړه. مېرمنې یې همداسې وکړل. هغه صحابي رضي الله عنه په تیاره کې داسې ښکاره کړه چې ګواکې هغه هم په ډوډۍ کې شریک دی. په دې ډول د رسول اکرم ﷺ د مېلمه پر خدمت الله تعالی وحي نازله کړه.'),
          ('The next day the Noble Prophet ﷺ was extremely pleased with that Companion and praised his deed. For us there is a very great lesson in this hadith, that we should not consider the guest a cause of trouble but rather a cause of mercy, and leave no stone unturned in serving him. Allah the Exalted is the One who creates blessing in our wealth.', 'اگلے روز نبی کریم صلی اللہ علیہ وآلہٖ وسلم اس صحابی سے بے حد خوش ہوئے اور ان کے عمل کی تعریف فرمائی۔ ہمارے لیے اس حدیث میں بہت بڑا سبق ہے کہ ہم مہمان کو باعثِ زحمت نہ سمجھیں بلکہ باعثِ رحمت جانیں اور اس کی خدمت کرنے میں کوئی کسر باقی نہ رکھیں۔ اللہ تعالیٰ ہمارے مالوں میں برکت پیدا کرنے والا ہے۔', 'بله ورځ نبي کریم ﷺ له هغه صحابي ډېر خوشاله شو او د هغه عمل یې وستایه. زموږ لپاره په دې حدیث کې ډېر لوی درس دی چې مېلمه د زحمت سبب ونه ګڼو، بلکې د رحمت سبب یې وګڼو، او د هغه په خدمت کې هېڅ کمی پاتې نه کړو. الله تعالی زموږ په مالونو کې برکت پیدا کوونکی دی.')])
    BOOK.save(72, [(2, r1), (2, rec(t, 2, 135, 72, [135]))], issues=[{'id': 'iski12-pdf072', 'unit': 2, 'printedPage': 134,
               'description': 'p.134: the right edge of the page is cut off in the scan, clipping the heading "حدیث" and a few line starts; supplied in [brackets]. p.135: the start of the translation line and the first words of the next paragraph are hidden by a fold; supplied in [brackets]. Student handwriting at the start of the translation on p.134 excluded.'}])


if __name__ == '__main__':
    p72()
